static Mesh3D Grid(unsigned side){Mesh3D mesh;for(unsigned z=0;z<=side;++z)for(unsigned x=0;x<=side;++x){const float u=float(x)/side,v=float(z)/side,height=.08f*std::sin(u*6.2831853f)*std::sin(v*6.2831853f);mesh.vertices.push_back({u*4-2,height,v*4-2,PackNormalSnorm8({0,1,0},.35f+.5f*u),PackColorRgba8({u,v,1-u,1}),u,v});}const unsigned stride=side+1;for(unsigned z=0;z<side;++z)for(unsigned x=0;x<side;++x){const uint32_t a=z*stride+x,b=a+1,c=a+stride,d=c+1;mesh.indices.insert(mesh.indices.end(),{a,c,b,b,c,d});}return mesh;}
static float OrientationY(const Mesh3D& mesh,size_t offset){const Vec3 a{mesh.vertices[mesh.indices[offset]].x,mesh.vertices[mesh.indices[offset]].y,mesh.vertices[mesh.indices[offset]].z},b{mesh.vertices[mesh.indices[offset+1]].x,mesh.vertices[mesh.indices[offset+1]].y,mesh.vertices[mesh.indices[offset+1]].z},c{mesh.vertices[mesh.indices[offset+2]].x,mesh.vertices[mesh.indices[offset+2]].y,mesh.vertices[mesh.indices[offset+2]].z};return Cross(b-a,c-a).y;}
static std::array<uint32_t,3> Triangle(const Mesh3D& mesh,size_t offset){return{mesh.indices[offset],mesh.indices[offset+1],mesh.indices[offset+2]};}
static bool SameVertex(const Vertex3D& left,const Vertex3D& right){return left.x==right.x&&left.y==right.y&&left.z==right.z&&left.normal==right.normal&&left.color==right.color&&left.u==right.u&&left.v==right.v;}
static bool SameMesh(const Mesh3D& left,const Mesh3D& right){if(left.vertices.size()!=right.vertices.size()||left.indices!=right.indices)return false;for(size_t index=0;index<left.vertices.size();++index)if(!SameVertex(left.vertices[index],right.vertices[index]))return false;return true;}
static bool SameMeshChain(const std::vector<Mesh3D>& left,const std::vector<Mesh3D>& right){if(left.size()!=right.size())return false;for(size_t level=0;level<left.size();++level)if(!SameMesh(left[level],right[level]))return false;return true;}
static bool InsideBounds(const Mesh3D& mesh,const MeshBounds3D& bounds){const Vec3 minimum=bounds.center-bounds.extents,maximum=bounds.center+bounds.extents;for(const Vertex3D& vertex:mesh.vertices)if(vertex.x<minimum.x-.001f||vertex.x>maximum.x+.001f||vertex.y<minimum.y-.001f||vertex.y>maximum.y+.001f||vertex.z<minimum.z-.001f||vertex.z>maximum.z+.001f)return false;return true;}
static size_t CacheMisses(const Mesh3D& mesh,size_t cacheSize){std::vector<uint32_t> cache;size_t misses{};for(uint32_t index:mesh.indices){const auto found=std::find(cache.begin(),cache.end(),index);if(found==cache.end())++misses;else cache.erase(found);cache.insert(cache.begin(),index);if(cache.size()>cacheSize)cache.pop_back();}return misses;}
